CREATE TABLE `crm_quote` (
  `quote_id` varchar(100) NOT NULL COMMENT 'ID',
  `quote_code` varchar(100) NOT NULL COMMENT '编号',
  `opty_id` varchar(100) NOT NULL COMMENT '机会ID',
  `opty_name` varchar(100) NOT NULL COMMENT '机会编号',
  `quote_name` varchar(255) DEFAULT '' COMMENT '名称',
  `quote_type` varchar(100) DEFAULT '' COMMENT '类型',
  `amount` decimal(10,2) DEFAULT '0.00' COMMENT '未含税金额',
  `discount` decimal(10,2) DEFAULT '0.00' COMMENT '折扣',
  `tax_ratio` decimal(10,2) DEFAULT '0.00' COMMENT '税率',
  `tax_amount` decimal(10,2) DEFAULT '0.00' COMMENT '税额',
  `discount_amount` decimal(10,2) DEFAULT '0.00' COMMENT '折扣额',
  `total_amount` decimal(10,2) DEFAULT '0.00' COMMENT '总金额',
  `account_id` varchar(100) DEFAULT '' COMMENT '客户ID',
  `account_name` varchar(100) DEFAULT '' COMMENT '客户名',
  `contact_id` varchar(100) DEFAULT '' COMMENT '联系人ID',
  `contact_name` varchar(100) DEFAULT '' COMMENT '联系人',
  `contact_phone` varchar(100) DEFAULT '' COMMENT '联系电话',
  `owner_id` varchar(100) DEFAULT '' COMMENT '销售id',
  `owner_name` varchar(100) DEFAULT '' COMMENT '销售',
  `payment_terms` int DEFAULT '12' COMMENT '合同月',
  `quote_date` date DEFAULT NULL COMMENT '报价日期',
  `expired_date` date DEFAULT NULL COMMENT '失效日期',
  `effective_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `approval_status` varchar(100) DEFAULT '' COMMENT '审批状态',
  `create_by` varchar(20) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(20) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`quote_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='报价单表';
