CREATE TABLE `sys_ems_corres` (
  `corres_id` bigint NOT NULL AUTO_INCREMENT COMMENT '文件id',
  `category` varchar(40) DEFAULT '0' COMMENT '文件类型id',
  `isBelongtoCase` char(1) DEFAULT '0' COMMENT '是否属于case',
  `folder_id` bigint DEFAULT '0' COMMENT '文件夹id',
  `case_id` varchar(40) DEFAULT '0' COMMENT 'case id',
  `file_title` varchar(300) DEFAULT '' COMMENT '文件名称',
  `file_name` varchar(300) DEFAULT '' COMMENT '文件系统名称',
  `file_type` varchar(200) DEFAULT '' COMMENT '文件类别',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小',
  `order_num` int DEFAULT '0' COMMENT '显示顺序',
  `status` char(1) DEFAULT '0' COMMENT '类型状态',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`corres_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='文件信息';
