--

DROP TABLE IF EXISTS `sys_re_acceptance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_re_acceptance` (
  `accept_id` varchar(100) NOT NULL COMMENT '编码',
  `project_id` varchar(100) DEFAULT NULL COMMENT '项目编号',
  `task_id` varchar(255) DEFAULT '0' COMMENT '任务编号',
