DROP TABLE IF EXISTS `sys_re_casetype`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_re_casetype` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `case_type_id` varchar(255) DEFAULT '' COMMENT 'case编码',
  `case_sort` int DEFAULT '0' COMMENT '排序',
  `case_label` varchar(255) DEFAULT '' COMMENT '标签',
  `case_name` varchar(255) DEFAULT '' COMMENT 'case名称',
  `case_version` varchar(20) DEFAULT '' COMMENT 'case版本',
  `case_application_id` varchar(255) DEFAULT NULL COMMENT 'case应用id',
  `case_urgency` int DEFAULT '10' COMMENT '默认的紧急度',
  `case_prefix` varchar(255) DEFAULT 'C-' COMMENT 'case前缀',
  `case_icon` varchar(30) DEFAULT 'el-icon-suitcase' COMMENT 'case图标',
  `case_availability` char(1) DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `case_status_work` varchar(255) DEFAULT '0' COMMENT 'case状态',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `case_description` varchar(500) DEFAULT NULL COMMENT 'case描述',
  `initial_data` varchar(45) DEFAULT NULL,
  `field_tracking` int DEFAULT NULL,
  `email_initial_account` varchar(45) DEFAULT NULL,
  `goal` date DEFAULT NULL,
  `deadline` date DEFAULT NULL,
  `worklist_notify` int DEFAULT NULL,
  `workgroup_notify` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='case定义表';
/*!40101 SET character_set_client = @saved_cs_client */;

