--
-- Table structure for table `sys_re_datafield`
--

DROP TABLE IF EXISTS `sys_re_datafield`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_re_datafield` (
  `field_id` varchar(100) NOT NULL COMMENT '字段编码',
  `field_sort` int DEFAULT '0' COMMENT '排序',
  `field_label` varchar(255) DEFAULT '' COMMENT '字段中文名',
  `field_name` varchar(255) DEFAULT '' COMMENT '字段名称',
  `field_type` varchar(255) DEFAULT '' COMMENT '字段类型',
  `dataobj_id` varchar(100) DEFAULT NULL COMMENT '数据对象id',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `is_show` char(1) DEFAULT 'Y' COMMENT '是否显示',
  `field_category` varchar(45) DEFAULT 'fixed' COMMENT '字段类别',
  PRIMARY KEY (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='表字段表';
/*!40101 SET character_set_client = @saved_cs_client */;

