DROP TABLE IF EXISTS `sys_ru_caseinstance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_ru_caseinstance` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `py_case_id` varchar(255) DEFAULT '' COMMENT 'caseId',
  `py_label` varchar(255) DEFAULT '' COMMENT '标签',
  `py_name` varchar(255) DEFAULT '' COMMENT 'case名称',
  `case_type_id` varchar(255) DEFAULT NULL COMMENT 'case定义id',
  `py_urgency` int DEFAULT '10' COMMENT '默认的紧急度',
  `py_current_stage` varchar(255) DEFAULT '' COMMENT '当前阶段',
  `py_status_work` varchar(255) DEFAULT '' COMMENT '状态',
  `py_case_structure` text COMMENT 'case结构',
  `py_work_page` text COMMENT '数据',
  `px_create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `px_create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `py_update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `py_update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `py_description` varchar(500) DEFAULT NULL COMMENT 'case描述',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=363 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='case实例表';
